(()=>{
 const section=document.getElementById('sound-example');if(!section)return;
 const id=document.body.dataset.effect,effect=effects.find(effect=>effect.id===id),button=document.getElementById('example-generate'),status=document.getElementById('example-status'),meter=document.getElementById('example-meter'),before=document.getElementById('example-before'),after=document.getElementById('example-after'),players=document.getElementById('example-players'),t=text=>window.SonicI18n?.translate(text)||text;let urls=[],token=0,working=false;
 const controls=effect.controls.map(control=>control[1]);if(id==='equalizer')controls.splice(0,controls.length,4,0,-5,2,3,-2,0,0);if(id==='trim'){controls[0]=20;controls[1]=85;}
 document.getElementById('example-settings').textContent=t('Example settings:')+' '+(effect.controls.length?effect.controls.map((control,i)=>control[0]+' '+controls[i]+control[4]).join(' · '):effect.name);
 function pause(){before.pause();after.pause();}
 function clear(){token++;working=false;button.disabled=false;meter.hidden=true;players.hidden=true;pause();for(const url of urls)URL.revokeObjectURL(url);urls=[];before.removeAttribute('src');after.removeAttribute('src');before.load();after.load();}
 function makeSample(){const Offline=window.OfflineAudioContext||window.webkitOfflineAudioContext,rate=22050,seconds=6,buffer=new Offline(2,1,rate).createBuffer(2,rate*seconds,rate),notes=[261.63,329.63,392,493.88,440,293.66,349.23,523.25];let seed=98765;for(let i=0;i<buffer.length;i++){const time=i/rate,beat=time%.375,note=notes[Math.floor(time/.375)%notes.length],envelope=Math.exp(-beat*9)*Math.min(1,time*12)*Math.min(1,(seconds-time)*4);seed=(1664525*seed+1013904223)>>>0;const percussion=(seed/2147483648-1)*Math.exp(-beat*100)*.045;for(let channel=0;channel<2;channel++){const phase=channel*.3,melody=Math.sin(2*Math.PI*note*time+phase)*.17+Math.sin(2*Math.PI*note*2*time+phase)*.045,bass=Math.sin(2*Math.PI*65.4*time)*.10;buffer.getChannelData(channel)[i]=(melody+bass)*envelope+percussion;}}return buffer;}
 button.onclick=async()=>{if(working)return;clear();const ticket=++token;working=true;button.disabled=true;status.textContent=t('Creating your before-and-after example…');meter.hidden=false;meter.value=0;players.hidden=true;
  try{const original=makeSample(),values={[id]:{enabled:true,controls}},result=await SonicDSP.render(original,[id],values,fraction=>{if(ticket===token)meter.value=Math.round(fraction*90);});if(ticket!==token)return;const originalBlob=await SonicDSP.wavAsync(original),resultBlob=await SonicDSP.wavAsync(result,fraction=>{if(ticket===token)meter.value=90+Math.round(fraction*10);});if(ticket!==token)return;urls=[URL.createObjectURL(originalBlob),URL.createObjectURL(resultBlob)];before.src=urls[0];after.src=urls[1];players.hidden=false;status.textContent=t('Compare the original sample with the effect. Your uploaded audio is unchanged.');meter.value=100;
  }catch(error){if(ticket===token)status.textContent=t('Example could not be created. Please try again.');}finally{if(ticket===token){working=false;button.disabled=false;meter.hidden=true;}}
 };
 for(const audio of [before,after])audio.addEventListener('play',()=>{window.SonicStudio?.pausePlayback();window.SonicWorkflow?.pause();(audio===before?after:before).pause();});
 window.SonicExamples={pause};window.addEventListener('pagehide',clear);
})();
